#[test]
fn router_matches_oracle() {
    let x = [
        0.304717093706131, -1.039984107017517, 0.7504512071609497, 0.9405646920204163,
        -1.9510351419448853, -1.3021794557571411, 0.12784039974212646, -0.31624260544776917,
        -0.01680115796625614, -0.8530439138412476, 0.879397988319397, 0.7777919173240662,
        0.06603069603443146, 1.1272412538528442, 0.46750932931900024, -0.8592924475669861,
    ];
    let gate = [
        -0.8781523704528809, -0.334123432636261, 0.9159025549888611, -1.3263927698135376,
        0.030631491914391518, -0.4841694235801697, -0.3276731073856354, 1.0027577877044678,
        0.5381154417991638, 1.3373980522155762, -0.1545056849718094, -0.6959426403045654,
        -0.2238588184118271, 0.2424967885017395, 0.17657335102558136, -1.084388017654419,
        0.09048978239297867, 0.22822833061218262, 2.5174739360809326, 1.8768446445465088,
        -0.853243350982666, -0.2873833477497101, -1.4634419679641724, -0.590707004070282,
        0.3156050145626068, 1.2058535814285278, -0.7290838360786438, -0.6541464328765869,
        -2.1472890377044678, -0.16266591846942902, -1.0624144077301025, -0.5294394493103027,
        -0.8768607974052429, -0.09426255524158478, -1.7577283382415771, -1.4670451879501343,
        2.1292471885681152, -1.28742253780365, -1.096785545349121, 1.8369135856628418,
    ];
    let bias = [0.0, -2.0, 0.5, -1.0, 2.0];
    let want_idx = [4usize, 2, 4, 2];
    let want_wts = [
        0.0023169664200395346, 0.997683048248291, 0.0026159947738051414, 0.9973840117454529,
    ];
    let (idx, wts) = router(&x, &gate, &bias, 8, 5, 2);
    assert_eq!(idx, want_idx, "router indices must match exactly (T22)");
    assert_close(&wts, &want_wts, "router weights");
}

#[test]
fn embed_is_a_bit_exact_gather() {
    // [vocab=4, hidden=3]
    let table = [
        1.0, 2.0, 3.0, // token 0
        4.0, 5.0, 6.0, // token 1
        7.0, 8.0, 9.0, // token 2
        -1.0, -2.0, -3.0, // token 3
    ];
    let got = embed(&[2, 0, 3], &table, 4, 3);
    assert_eq!(got, vec![7.0, 8.0, 9.0, 1.0, 2.0, 3.0, -1.0, -2.0, -3.0]);
}
